Clase Cliente
    Privado Definir nombre Como Cadena;

    Metodo Constructor(unNombre Como Cadena)
        Este.nombre <- unNombre;
    FinMetodo

    Publico Metodo Nombre() Como Cadena
        Retornar Este.nombre;
    FinMetodo
FinClase

Clase Pedido
    Privado Definir cliente Como Cliente;
    Privado Definir monto Como Entero;

    Metodo Constructor(unNombre Como Cadena, unMonto Como Entero)
        Este.cliente <- Nuevo Cliente(unNombre);
        Este.monto <- unMonto;
    FinMetodo

    Publico Metodo Resumen() Como Cadena
        Retornar Este.cliente.Nombre() + ": " + ATexto(Este.monto);
    FinMetodo
FinClase

Proceso EjecutarPedido
    Definir nombre Como Cadena;
    Definir monto Como Entero;
    Definir pedido Como Pedido;
    Leer nombre;
    Leer monto;
    pedido <- Nuevo Pedido(nombre, monto);
    Escribir pedido.Resumen();
FinProceso
